  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0, line = 1, col = 1

  const advance = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
