      const s = i
      let ok = true
      const run = (pred) => {
        let cnt = 0
        while (i < n) {
          if (pred(cs[i])) { advance(); cnt++ }
          else if (cs[i] === '_' && cnt > 0 && pred(cs[i + 1])) advance()
          else break
        }
        return cnt
