#!/usr/bin/env node
/**
 * `node src/cli.js tokens` prints every token of the source read from standard
 * input with its position, and `node src/cli.js stats` counts tokens by kind.
 */
import { readFileSync } from 'node:fs'
import { scan, ScanError } from './scan.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'tokens' && mode !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
let out = ''
try {
  const tokens = scan(readFileSync(0, 'utf8'))
  if (mode === 'tokens') {
    for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
  } else {
    for (const k of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
      out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
    }
    out += `total ${tokens.length}\n`
  }
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out)
